// ─── Custom Cursor ──────────────────────────────────────────────────────────
function useCursor(primary) {
  const pos  = useRef({x:0,y:0});
  const cur  = useRef({x:0,y:0});
  const raf  = useRef(null);

  useEffect(() => {
    const dotEl  = document.getElementById("cur-dot");
    const ringEl = document.getElementById("cur-ring");

    const onMove = e => {
      pos.current = {x:e.clientX,y:e.clientY};
      if(dotEl){dotEl.style.left=e.clientX+"px";dotEl.style.top=e.clientY+"px";}
      const hover = e.target.closest("button,a,[role=button],.svc-card,.cal-day,.slot,.tab-btn");
      document.body.classList.toggle("cursor-hover",!!hover);
    };
    const lerp=(a,b,t)=>a+(b-a)*t;
    const tick=()=>{
      cur.current.x=lerp(cur.current.x,pos.current.x,.1);
      cur.current.y=lerp(cur.current.y,pos.current.y,.1);
      if(ringEl){ringEl.style.left=cur.current.x+"px";ringEl.style.top=cur.current.y+"px";}
      raf.current=requestAnimationFrame(tick);
    };
    document.addEventListener("mousemove",onMove);
    raf.current=requestAnimationFrame(tick);
    return()=>{document.removeEventListener("mousemove",onMove);cancelAnimationFrame(raf.current);};
  },[]);

  useEffect(()=>{
    const dotEl=document.getElementById("cur-dot");
    const ringEl=document.getElementById("cur-ring");
    if(dotEl)dotEl.style.background=primary;
    if(ringEl)ringEl.style.borderColor=primary;
  },[primary]);
}

