// ─── Cleaning Video Component (Blob URL for sandbox compat) ────────────────
function CleaningVideo() {
  const [src, setSrc] = useState(null);
  useEffect(() => {
    try {
      const byteChars = atob(CLEANING_VIDEO_B64);
      const bytes = new Uint8Array(byteChars.length);
      for (let i = 0; i < byteChars.length; i++) bytes[i] = byteChars.charCodeAt(i);
      const blob = new Blob([bytes], { type: "video/mp4" });
      const url  = URL.createObjectURL(blob);
      setSrc(url);
      return () => URL.revokeObjectURL(url);
    } catch(e) { console.error("Video load error:", e); }
  }, []);

  if (!src) return (
    <div style={{width:"100%",aspectRatio:"16/9",background:"linear-gradient(135deg,#0a2540,#1565c0)",borderRadius:16,display:"flex",alignItems:"center",justifyContent:"center"}}>
      <div style={{width:40,height:40,borderRadius:"50%",border:"3px solid rgba(255,255,255,.3)",borderTopColor:"white",animation:"spin .8s linear infinite"}}/>
    </div>
  );
  return (
    <video autoPlay muted loop playsInline
      style={{width:"100%",borderRadius:16,objectFit:"cover",display:"block",boxShadow:"0 8px 30px rgba(0,0,0,.15)",aspectRatio:"16/9"}}>
      <source src={src} type="video/mp4"/>
    </video>
  );
}

